script:
const weekTitle = root_element.querySelector('[data-label="week-total"]');
const monthTitle = root_element.querySelector('[data-label="month-total"]');
const forecastTitle = root_element.querySelector('[data-label="week-forecast"]');
const hoursBalanceTitle = root_element.querySelector('[data-label="hours-balance"]');
const vacationTitle = root_element.querySelector('[data-label="vacation-remaining"]');

const weekTotal = root_element.querySelector('[data-field="week-total"]');
const weekStatus = root_element.querySelector('[data-field="week-status"]');
const monthTotal = root_element.querySelector('[data-field="month-total"]');
const monthStatus = root_element.querySelector('[data-field="month-status"]');
const weekForecast = root_element.querySelector('[data-field="week-forecast"]');
const hoursBalance = root_element.querySelector('[data-field="hours-balance"]');
const vacationCard = root_element.querySelector('[data-card="vacation"]');
const vacationRemaining = root_element.querySelector('[data-field="vacation-remaining"]');
const vacationStatus = root_element.querySelector('[data-field="vacation-status"]');

if (weekTitle) {
  weekTitle.textContent = __('Week Total');
}
if (monthTitle) {
  monthTitle.textContent = __('Month Total');
}
if (forecastTitle) {
  forecastTitle.textContent = __('Forecast');
}
if (hoursBalanceTitle) {
  hoursBalanceTitle.textContent = __('Hours Balance');
}
if (vacationTitle) {
  vacationTitle.textContent = __('Vacation Remaining');
}

function formatMinutes(totalMinutes) {
  const minutes = Math.max(0, Math.round(totalMinutes || 0));
  const hours = Math.floor(minutes / 60);
  const remainder = minutes % 60;
  return `${hours}:${String(remainder).padStart(2, '0')}`;
}

function formatSignedMinutes(totalMinutes) {
  const value = Math.round(totalMinutes || 0);
  const sign = value < 0 ? '-' : '';
  return `${sign}${formatMinutes(Math.abs(value))}`;
}

function formatVacationDays(value) {
  const rounded = Math.round(Number(value || 0) * 100) / 100;
  return Number.isFinite(rounded) ? rounded.toString() : '0';
}

function updateWeeklyStatus(totalMinutes, targetHours, targetPeriod) {
  if (targetPeriod === 'Monthly') {
    weekStatus.textContent = '';
    weekStatus.style.display = 'none';
    return;
  }

  weekStatus.style.display = '';
  if (!targetHours) {
    weekStatus.textContent = __('Weekly target not set.');
    weekStatus.style.color = '#6c757d';
    return;
  }
  const targetMinutes = Math.round(Number(targetHours) * 60);
  const diff = totalMinutes - targetMinutes;
  if (diff >= 0) {
    weekStatus.textContent = `${__('Over by')}: ${formatMinutes(diff)}`;
    weekStatus.style.color = '#28a745';
  } else {
    weekStatus.textContent = `${__('Remaining')}: ${formatMinutes(Math.abs(diff))}`;
    weekStatus.style.color = '#dc3545';
  }
}

function updateMonthlyStatus(totalMinutes, targetHours, targetPeriod) {
  if (targetPeriod === 'Weekly') {
    monthStatus.textContent = '';
    monthStatus.style.display = 'none';
    return;
  }

  monthStatus.style.display = '';
  if (!targetHours) {
    monthStatus.textContent = __('Monthly target not set.');
    monthStatus.style.color = '#6c757d';
    return;
  }
  const targetMinutes = Math.round(Number(targetHours) * 60);
  const diff = totalMinutes - targetMinutes;
  if (diff >= 0) {
    monthStatus.textContent = `${__('Over by')}: ${formatMinutes(diff)}`;
    monthStatus.style.color = '#28a745';
  } else {
    monthStatus.textContent = `${__('Remaining')}: ${formatMinutes(Math.abs(diff))}`;
    monthStatus.style.color = '#dc3545';
  }
}

function updateVacationSummary(vacation) {
  vacationCard.style.display = '';
  if (!vacation || !vacation.enabled) {
    vacationRemaining.textContent = '--';
    vacationStatus.textContent = __('Vacation is not configured.');
    vacationStatus.style.color = '#6c757d';
    return;
  }

  if (!vacation.valid) {
    vacationRemaining.textContent = '--';
    vacationStatus.textContent = vacation.error || __('Vacation balance is unavailable.');
    vacationStatus.style.color = '#dc3545';
    return;
  }

  const remaining = Number(vacation.remaining_days || 0);
  const used = Number(vacation.used_days || 0);
  const allowance = Number(vacation.allowance_days || 0);

  vacationRemaining.textContent = formatVacationDays(remaining);
  vacationStatus.textContent = __('Used {0} of {1} days.', [
    formatVacationDays(used),
    formatVacationDays(allowance),
  ]);
  vacationStatus.style.color = remaining < 0 ? '#dc3545' : '#6c757d';
}

function showProfileMissing(message) {
  const text = message || __('Time Tracking Profile is required.');
  weekStatus.textContent = text;
  weekStatus.style.display = '';
  weekStatus.style.color = '#dc3545';
  monthStatus.textContent = '';
  monthStatus.style.display = 'none';
  if (weekForecast) {
    weekForecast.textContent = '0:00';
  }
  vacationCard.style.display = 'none';
}

function updateSummary(data) {
  const weeklyMinutes = Number(data.weekly_total_minutes || 0);
  const monthlyMinutes = Number(data.monthly_total_minutes || 0);
  const weeklyForecastMinutes = Number(data.weekly_forecast_minutes || 0);
  const hoursBalanceMinutes = Number(data.hours_balance_minutes || 0);
  const targetPeriod = data.target_period || null;

  weekTotal.textContent = formatMinutes(weeklyMinutes);
  monthTotal.textContent = formatMinutes(monthlyMinutes);
  if (weekForecast) {
    weekForecast.textContent = formatMinutes(weeklyForecastMinutes);
  }
  hoursBalance.textContent = formatSignedMinutes(hoursBalanceMinutes);

  updateWeeklyStatus(weeklyMinutes, data.weekly_target_hours, targetPeriod);
  updateMonthlyStatus(monthlyMinutes, data.monthly_target_hours, targetPeriod);
  updateVacationSummary(data.vacation);
}

frappe.call({
  method: 'time_tracking.time_tracking.workspace_summary.get_workspace_summary',
  callback: function (r) {
    const message = r.message || {};
    if (message.profile_missing) {
      showProfileMissing(message.message);
      return;
    }
    updateSummary(message);
  },
});

style:
.tt-summary {
  display: flex;
  justify-content: center;
  margin: 6px 0 4px;
}

.tt-summary-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  width: 100%;
  justify-content: center;
}

.tt-summary-card {
  min-width: 260px;
  flex: 1 1 260px;
}

.tt-summary-value {
  font-size: 26px;
  font-weight: 600;
}

.tt-summary-status {
  font-size: 12px;
  color: #6c757d;
}
